-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_POLICY_EXCESS_STRUCTURE
--   anchor      : HUB_POLICY
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Excess Code
--   feeders     : 2 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        'VOLUNTARY_AGGREGATE' as EXCESS_CODE,
        VOLUNTARY_AGGREGATE_DEDUCTIBLE as EXCESS_AMOUNT,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_POLICY_K0__EMIT
    union all
    select
        md5(upper(HUB_POLICY_BK__K0)) as HUB_POLICY_HK,
        'VOLUNTARY_DEDUCTIBLE' as EXCESS_CODE,
        VOLUNTARY_DEDUCTIBLE as EXCESS_AMOUNT,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_pv') }}
    where HUB_POLICY_K0__EMIT
)), hashed as (select *,
        case when EXCESS_AMOUNT is not null
             then md5(upper(coalesce(EXCESS_AMOUNT::varchar,'')))
        end as SAT_POLICY_EXCESS_STRUCTURE_HASHDIFF
    from feeders)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_EXCESS_STRUCTURE_HASHDIFF is not null
  and EXCESS_CODE is not null
